// ============================================================================// 1. DIRECTIVAS DE PREPROCESADOR Y BIBLIOTECAS// Incorporan herramientas previas a la compilación.// ============================================================================// Biblioteca principal de entrada y salida estándar de datos (habilita cout y cin).#include <iostream>// Biblioteca para manipular el formato de impresión en pantalla (habilita setprecision y setw).#include <iomanip>// Biblioteca para el manej// o avanzado de cadenas de texto (habilita getline y to_string).#include <string>// Espacio de nombres que nos permite dejar de utilizar el prefijo "std::" cada vez que// queramos usar funciones u objetos estándar como cout, cin, string o endl.using namespace std;// ============================================================================// 2. FUNCIÓN PRINCIPAL// Punto de entrada obligatorio; toda ejecución de un programa en C++ comienza aquí// y ejecuta las instrucciones en orden secuencial de arriba hacia abajo// ============================================================================int main(){	// ========================================================================	// 3. VARIABLES, CONSTANTES, TIPOS DE DATOS Y NOMENCLATURA	// - Variable: espacio reservado en memoria RAM cuyo valor puede cambiar.	// - Constante: espacio en memoria cuyo valor no se puede modificar.	// Reglas para nombrarlas (identificadores): iniciar con letra, sin espacios	// ni símbolos especiales (solo guion bajo '_').	// ========================================================================	// Números enteros (sin decimales), usados típicamente para conteos.	// Nomenclatura simple:	int edad = 20;	// Números decimales de precisión estándar (usados para medidas).	// Nomenclatura snake_case (palabras separadas por guion bajo):	float precio_producto = 19.99f;	// Números decimales de alta precisión (usados para cálculos exactos).	double pi = 3.14159;	// Un único carácter o símbolo. SIEMPRE lleva comillas simples (' ').	char inicial = 'A';	// Cadena de texto (varios caracteres). SIEMPRE lleva comillas dobles (" ").	// Nomenclatura lowerCamelCase (primera palabra en minúscula, siguientes inician en mayúscula):	string nombreCliente = "Ana";	// Dato lógico o booleano. Solo almacena true (verdadero / 1) o false (falso / 0).	bool esActivo = true;	// Palabra clave 'const' para declarar constantes.	// Nomenclatura UPPER_CASE (todo en mayúsculas):	const int EDAD_MINIMA = 18;	// ========================================================================	// 4. SALIDA DE DATOS EN PANTALLA Y FORMATO DE IMPRESIÓN	// El operador << envía datos hacia la pantalla; permite encadenar valores.	// ========================================================================	// Impresión básica con salto de línea '\n' integrado dentro del texto.	cout << "Hola, mundo\n";	// Impresión encadenando texto literal, variables y 'endl' (salta de línea y vacía el buffer).	cout << "Cliente: " << nombreCliente << " | Inicial: " << inicial << endl;	// Alternativa heredada del lenguaje C para imprimir (cout es el estándar en C++).	printf("Edad impresa con estilo printf: %d\n", edad);	// Formato de números decimales y ancho de impresión (requiere <iomanip>):	// 'fixed' fija la notación decimal y 'setprecision(n)' define cuántos decimales mostrar.	cout << fixed << setprecision(2);	cout << "Valor de Pi con 2 decimales: " << pi << endl;	// 'setw(n)' define un ancho mínimo de espacios para alinear el valor impreso.	cout << "Numero alineado con ancho 10:" << setw(10) << 25 << endl;	// ========================================================================	// 5. CONCATENACIÓN DE CADENAS (STRING)	// El operador '+' une textos. Para unir números con strings, primero se	// convierten a texto usando la función to_string().	// ========================================================================	string apellido = "Perez";	string nombre_completo = nombreCliente + " " + apellido;	// Mezclando texto y una variable int convertida a string:	string mensaje = "Hola " + nombre_completo + ", tienes " + to_string(edad) + " anios.";	cout << mensaje << endl;	// ========================================================================	// 6. ENTRADA DE DATOS POR TECLADO	// El operador >> junto a 'cin' lee lo que el usuario escribe y lo guarda.	// ========================================================================	double n1, n2;	cout << "\nIngresa dos numeros separados por espacio: ";	// Se pueden encadenar varias lecturas en una misma línea con cin >> :	cin >> n1 >> n2;	// NOTA TÉCNICA: 'cin >>' se detiene en el primer espacio en blanco y deja un Enter ('\n')	// pendiente en el buffer. Limpiamos ese Enter con cin.ignore() antes de usar getline().	cin.ignore();	// Para leer textos que incluyan espacios (ej. nombres completos o frases),	// se utiliza getline(cin, variable) en lugar de cin >>.	string carrera;	cout << "Ingresa tu carrera (puede llevar espacios): ";	getline(cin, carrera);	cout << "Estudias: " << carrera << endl;	// ========================================================================	// 7. OPERADORES Y LINEALIZACIÓN DE EXPRESIONES	// El computador lee las instrucciones en una sola línea, por lo que usamos	// paréntesis para agrupar y respetar el orden matemático.	// ========================================================================	// A) Operadores Aritméticos: + (suma), - (resta), * (multiplicación), / (división), % (residuo).	double suma = n1 + n2;	double promedio = (n1 + n2) / 2.0; // Linealización con paréntesis	int residuo = 10 % 3; // Devuelve 1 (el sobrante de dividir 10 entre 3, solo para enteros)	cout << "Suma: " << suma << " | Promedio: " << promedio << " | Residuo 10%3: " << residuo << endl;	// B) Operadores de Asignación Compuesta: =, +=, -=, *=, /=	int contador = 5;	contador += 10;   // Equivale a: contador = contador + 10 (ahora vale 15)	contador *= 2;    // Equivale a: contador = contador * 2 (ahora vale 30)	// C) Operadores Relacionales (Comparación):	// == (igual a), != (distinto de), > (mayor), < (menor), >= (mayor o igual), <= (menor o igual).	// Toda comparación devuelve siempre un valor booleano: true (1) o false (0).	bool comparacion = (n1 == n2);	// D) Operadores Lógicos:	// && (AND / Y): true solo si AMBAS condiciones son verdaderas.	// || (OR / O):  true si AL MENOS UNA condición es verdadera.	// !  (NOT / NO): invierte el valor lógico (!true -> false).	// Orden de prioridad al evaluar: 1ro '!', 2do '&&', 3ro '||'.	bool tieneCarnet = true;	bool puedeConducir = (edad >= EDAD_MINIMA && tieneCarnet);	// ========================================================================	// 8. ESTRUCTURAS SELECTIVAS O CONDICIONALES	// Permiten que el programa tome decisiones según una expresión lógica.	// ========================================================================	// --- 8.1 CONDICIONAL SIMPLE (if) ---	// Ejecuta el bloque entre llaves { } solo si la condición es true. Si es false, lo salta.	// CUIDADO: Usar siempre '==' para comparar; usar un solo '=' dentro del if asigna el valor	// y provoca un error lógico grave.	int stock = 3;	if (stock < 5) {		cout << "\nAlerta: Reponer inventario." << endl;	}	// --- 8.2 CONDICIONAL DOBLE (if - else) ---	// Toma uno de dos caminos posibles: ejecuta el primer bloque si es true, o el 'else' si es false.	int nota = 65;	if (nota >= 70) {		cout << "Estado: Aprobado" << endl;	}	else {		cout << "Estado: Reprobado" << endl;	}	// --- 8.3 OPERADOR TERNARIO (? :) ---	// Forma abreviada del if-else en una sola línea para asignar o imprimir un valor rápido.	// Sintaxis: (condicion) ? valor_si_verdadero : valor_si_falso;	string estadoTernario = (nota >= 70) ? "Aprobado" : "Reprobado";	cout << "Con operador ternario: " << estadoTernario << endl;	// --- 8.4 CONDICIONAL MÚLTIPLE (else if) ---	// Evalúa varias condiciones en cascada; apenas una se cumple, ejecuta su bloque y descarta el resto.	// REGLA DE ORO: Ordenar siempre desde la condición más específica/exigente hacia la más general.	int calificacion = 85;	if (calificacion >= 90) {		cout << "Literal: A (Excelente)" << endl;	}	else if (calificacion >= 80) {		cout << "Literal: B (Muy bueno)" << endl;	}	else if (calificacion >= 70) {		cout << "Literal: C (Aprobado)" << endl;	}	else { // Se ejecuta si ninguna de las condiciones anteriores se cumplió		cout << "Literal: D (Reprobado)" << endl;	}	// --- 8.5 CONDICIONALES ANIDADOS ---	// Es un condicional dentro de otro. Buena práctica: evitar más de 2 o 3 niveles de anidación.	bool tieneBoleto = false;	if (edad >= 18) {		if (tieneBoleto) {			cout << "Acceso: Puede pasar al evento." << endl;		}		else {			cout << "Acceso: Mayor de edad, pero debe comprar su boleto." << endl;		}	}	else {		cout << "Acceso: Menor de edad, no puede pasar." << endl;	}	// Ejemplo clásico combinando operadores lógicos y módulo (%): Año bisiesto.	int anio = 2024;	if ((anio % 4 == 0 && anio % 100 != 0) || anio % 400 == 0) {		cout << anio << " es un anio bisiesto." << endl;	}	else {		cout << anio << " no es bisiesto." << endl;	}	// --- 8.6 ESTRUCTURA SWITCH ---	// Compara UNA sola variable contra varios valores exactos (cases).	// RESTRICCIÓN: Solo admite variables de tipo 'int' o 'char' (no admite rangos ni 'string').	char operador = '/';	double a = 10.0, b = 2.0;	switch (operador) {	case '+': // Si operador es exactamente '+'		cout << "Resultado suma: " << (a + b) << endl;		break; // 'break' detiene el switch; si lo olvidas, sigue ejecutando el case de abajo.	case '-':		cout << "Resultado resta: " << (a - b) << endl;		break;	case '*':		cout << "Resultado multiplicacion: " << (a * b) << endl;		break;	case '/':		// Se puede colocar un 'if' dentro de un 'case' para validar datos:		if (b != 0) {			cout << "Resultado division: " << (a / b) << endl;		}		else {			cout << "Error: No se puede dividir entre cero." << endl;		}		break;	default: // Opcional: se ejecuta si ningún 'case' anterior coincide con el valor.		cout << "Operador invalido." << endl;		break;	}	// Agrupación de casos en switch: varios 'case' seguidos sin 'break' comparten la misma acción.	char letra = 'e';	switch (letra) {	case 'a':	case 'e':	case 'i':	case 'o':	case 'u':		cout << "La letra '" << letra << "' es una vocal." << endl;		break;	default:		cout << "La letra '" << letra << "' es una consonante." << endl;		break;	}	// ========================================================================	// 9. ESTRUCTURAS REPETITIVAS O BUCLES (CICLOS)	// Permiten repetir un bloque de código varias veces mientras se cumpla una condición.	// Conceptos clave:	// - Contador: variable que incrementa o decrementa en un valor fijo (ej. i++, k--).	// - Acumulador: variable que suma valores variables en cada vuelta (se inicializa en 0).	// ========================================================================	// --- 9.1 BUCLE FOR (Ciclo con cantidad de repeticiones conocidas) ---	// Ideal para: tablas de multiplicar, contadores, listas y repeticiones exactas.	// Sintaxis: for (inicialización; condición_límite; incremento_o_decremento)	// A) Recorrido ascendente (incremento de 1 en 1 con k++) y uso de acumulador:	int sumaAcumulada = 0; // El acumulador SIEMPRE se inicializa en 0 antes del bucle	cout << "\n--- Bucle FOR ascendente y Acumulador (1 al 5) ---" << endl;	for (int i = 1; i <= 5; i++) {		sumaAcumulada += i; // Equivale a: sumaAcumulada = sumaAcumulada + i		cout << "Vuelta " << i << " -> Acumulado: " << sumaAcumulada << endl;	}	cout << "Total acumulado: " << sumaAcumulada << endl;	// B) Recorrido descendente (decremento de 1 en 1 con k--):	cout << "\n--- Bucle FOR descendente (5 al 1) ---" << endl;	for (int k = 5; k >= 1; k--) {		cout << k << " ";	}	cout << endl;	// C) Bucle FOR con límite dinámico (definido por el usuario) y cálculo de promedio:	int cantidadEmpleados;	double sueldoEmpleado, sumaSueldos = 0, promedioSueldos;	cout << "\nIngresa la cantidad de empleados a promediar: ";	cin >> cantidadEmpleados;	for (int i = 1; i <= cantidadEmpleados; i++) {		cout << "Ingresa el sueldo del empleado No." << i << ": ";		cin >> sueldoEmpleado;		sumaSueldos += sueldoEmpleado; // Acumula cada sueldo ingresado	}	promedioSueldos = sumaSueldos / cantidadEmpleados;	cout << "El sueldo promedio es: " << promedioSueldos << endl;	// --- 9.2 BUCLE WHILE (Ciclo controlado por condición o valor centinela) ---	// Ideal cuando NO sabemos cuántas veces se repetirá el ciclo, sino que depende	// de que el usuario ingrese un valor específico de salida (ej. ingresar 0 para terminar).	// Sintaxis: while (condición) { ... } -> Evalúa la condición ANTES de entrar al bloque.	int numeroLeido;	cout << "\n--- Bucle WHILE (Ingresa 0 para terminar) ---" << endl;	cout << "Ingrese un numero: ";	cin >> numeroLeido; // Lectura inicial antes del while	while (numeroLeido != 0) {		cout << "Ingresaste: " << numeroLeido << endl;		cout << "Ingrese otro numero (0 para salir): ";		cin >> numeroLeido; // Lectura de actualización dentro del while para evitar un bucle infinito	}	cout << "Fin del bucle while." << endl;	// Indica al sistema operativo que el programa finalizó correctamente.	return 0;}